703	export async function verifyHoldoutReactCypressRwaEvidence(rootDir = '.'): Promise<{
704		valid: true;
705		digest: string;
706		artifacts: number;
707		receipt: HoldoutReactCypressRwaReceipt;
708	}> {
709		const root = resolve(rootDir);
710		const published = parseHoldoutReactCypressRwaReceipt(
711			JSON.parse(await readFile(join(root, HOLDOUT_REACT_CYPRESS_RWA_RECEIPT_PATH), 'utf8')),
712		);
713		const derived = await deriveHoldoutReactCypressRwaReceipt(root);
714		if (canonicalize(published) !== canonicalize(derived))
715			throw new Error('Cypress RWA holdout receipt does not match its committed run evidence');
716		if (
717			(await readFile(join(root, HOLDOUT_REACT_CYPRESS_RWA_MARKDOWN_PATH), 'utf8')) !==
718			renderHoldoutReactCypressRwaReceipt(published)
719		)
720			throw new Error('Cypress RWA holdout human receipt differs');
721		return {
722			valid: true as const,
723			digest: published.integrity.canonicalDigest,
724			artifacts: published.runEvidence.length,
725			receipt: published,
726		};
727	}
