export async function startStaticServer(
	staticRoot: string,
	options: {
		profile?: 'current-witness' | 'canonical-t060';
		diagnosticEvent?: (
			event: Omit<WitnessDifferentialEvent, 'sequence' | 'timestampMs'>,
