				200,
				CONTENT_TYPES[extname(result.file)] ?? 'application/octet-stream',
				result.body,
				relative(staticRoot, result.file),
			);
		})().catch((error: unknown) => {
			failures.push(error instanceof Error ? error.message : String(error));
